#include <cstdint>
#include <cstring>
#include <cmath>
#include <cstdio>
#include <initializer_list>
template<class T,class U>T word(U value){T result;std::memcpy(&result,&value,sizeof(result));return result;}
int main(){unsigned cases=0,epsilonOdd=0,epsilonErrors=0,halfErrors=0,productOdd=0,noProductParityErrors=0;for(unsigned b=0;b<65536;b++){if((b&0x7c00)==0x7c00)continue;double x=word<_Float16>(uint16_t(b));for(uint16_t other:{uint16_t(0),uint16_t(0x8000),uint16_t(1),uint16_t(3),uint16_t(0x0c01),uint16_t(0x1001),uint16_t(0x3c00),uint16_t(0xbc00),uint16_t(0x3555),uint16_t(0x7bff),uint16_t(0xfbff)}){double y=word<_Float16>(other);float sum=float(x*x)+float(y*y);float mean=sum/2.0f;double value=double(mean)+double(1e-6f);uint64_t raw=word<uint64_t>(value);if((raw&UINT64_C(536870911))==UINT64_C(268435456)&&((raw>>29)&1))epsilonOdd++;double noParity=word<double>((raw+UINT64_C(268435455))&UINT64_C(18446744073172680704));double rounded=float(value);if(word<uint64_t>(noParity)!=word<uint64_t>(rounded)){if(epsilonErrors<3)std::printf("epsilonCounterexample x=%04x y=%04x source=%016llx expected=%016llx noParity=%016llx\n",b,other,(unsigned long long)raw,(unsigned long long)word<uint64_t>(rounded),(unsigned long long)word<uint64_t>(noParity));epsilonErrors++;}float inverse=1.0f/std::sqrt(float(value));double product=x*double(inverse);uint64_t p=word<uint64_t>(product);if((p&UINT64_C(536870911))==UINT64_C(268435456)&&((p>>29)&1))productOdd++;double expected=static_cast<_Float16>(float(product));double withoutParity=word<double>((p+UINT64_C(268435455))&UINT64_C(18446744073172680704));double storedWithoutParity=static_cast<_Float16>(withoutParity);if(word<uint64_t>(expected)!=word<uint64_t>(storedWithoutParity)){if(noProductParityErrors<3)std::printf("productParityCounterexample x=%04x y=%04x source=%016llx expected=%016llx simplified=%016llx\n",b,other,(unsigned long long)p,(unsigned long long)word<uint64_t>(expected),(unsigned long long)word<uint64_t>(storedWithoutParity));noProductParityErrors++;}double direct=static_cast<_Float16>(product);if(word<uint64_t>(expected)!=word<uint64_t>(direct)){if(halfErrors<3)std::printf("halfCounterexample x=%04x y=%04x source=%016llx expected=%016llx direct=%016llx\n",b,other,(unsigned long long)p,(unsigned long long)word<uint64_t>(expected),(unsigned long long)word<uint64_t>(direct));halfErrors++;}cases++;}}std::printf("RMS rounding frontier: cases=%u epsilonOddTies=%u missingEpsilonParityErrors=%u productOddTies=%u directHalfErrors=%u missingProductParityErrors=%u\n",cases,epsilonOdd,epsilonErrors,productOdd,halfErrors,noProductParityErrors);return (epsilonErrors&&halfErrors)?0:1;}
